package org.novasos.healthysv2.maternalandchildhealth;
import static org.assertj.core.api.Assertions.*;import java.math.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;

class MaternalChildTests{
 @Test void pregnancyLifecycleIncludesPrenatalRiskDeliveryAndPostpartum(){UUID mother=UUID.randomUUID(),child=UUID.randomUUID();var p=Pregnancy.start(mother,LocalDate.now().minusMonths(6),null,LocalDate.now().plusMonths(3));var visit=p.addVisit(null,UUID.randomUUID(),Instant.now(),24,new BigDecimal("70"),120,80,145,"Normal");var risk=p.addRisk("GESTATIONAL_DIABETES","HIGH","Monitor glucose");p.resolveRisk(risk.getId());var delivery=p.deliver(UUID.randomUUID(),Instant.now(),"VAGINAL",UUID.randomUUID(),null,"Healthy",List.of(new Pregnancy.NewbornData(child,1,new BigDecimal("3.2"),new BigDecimal("50"),new BigDecimal("35"),(short)8,(short)9)));var postpartum=p.addPostpartumVisit(mother,UUID.randomUUID(),Instant.now(),"Stable","COMPLETED");assertThat(visit.getGestationalAgeWeeks()).isEqualTo(24);assertThat(risk.getStatus()).isEqualTo("RESOLVED");assertThat(delivery.getNewborns()).singleElement().extracting(Newborn::getChildPatientId).isEqualTo(child);assertThat(postpartum.getStatus()).isEqualTo("COMPLETED");assertThat(p.getStatus()).isEqualTo("DELIVERED");assertThatThrownBy(()->p.addRisk("OTHER","LOW",null)).isInstanceOf(IllegalStateException.class);}
 @Test void childRecordComputesBmiAndRejectsEmptyGrowth(){var r=ChildHealthRecord.open(UUID.randomUUID(),UUID.randomUUID());var m=r.addMeasurement(Instant.now(),new BigDecimal("10"),new BigDecimal("100"),null,UUID.randomUUID());assertThat(m.getBmi()).isEqualByComparingTo("10.00");assertThatThrownBy(()->r.addMeasurement(Instant.now(),null,null,null,null)).isInstanceOf(IllegalArgumentException.class);}
 @Test void rejectsInconsistentPregnancyDatesAndDuplicateBirthOrder(){assertThatThrownBy(()->Pregnancy.start(UUID.randomUUID(),LocalDate.now(),null,LocalDate.now().minusDays(1))).isInstanceOf(IllegalArgumentException.class);var p=Pregnancy.start(UUID.randomUUID(),LocalDate.now().minusMonths(2),null,LocalDate.now().plusMonths(7));var newborn=new Pregnancy.NewbornData(UUID.randomUUID(),1,null,null,null,null,null);assertThatThrownBy(()->p.deliver(null,Instant.now(),"VAGINAL",null,null,null,List.of(newborn,new Pregnancy.NewbornData(UUID.randomUUID(),1,null,null,null,null,null)))).isInstanceOf(IllegalArgumentException.class);}
}
